insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('젤리 (Jellies)', '메리 커티스 래트클리프 (Mary Curtis Ratcliff)', '반투명 원반들이 모노필라멘트에 매달려 공기 흐름에 천천히 회전하며 벽에 부드러운 그림자를 드리우는 매달림형 키네틱 조각.', 2018, '폴리에스터·타이벡에 아크릴과 잉크, 리넨, 스틸, 모노필라멘트 (56×66×62 in)', NULL, ARRAY['키네틱아트','모빌','그림자','스틸','래트클리프']::text[], 'https://images.kctikinec.cloud/works/001.jpg', 'https://images.kctikinec.cloud/texts/001.txt', NULL, 0.314, 'CC BY-SA 4.0', 'Mary Curtis Ratcliff / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:%22Jellies%22_by_Mary_Curtis_Ratcliff.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('크로마 VII (Chroma VII)', '김윤철 (Yunchul Kim)', '수백 개의 홍채빛 셀형 모듈이 거대한 나선 고리를 이루며 유동적으로 움직이고 색이 변하는 대형 키네틱·색채 설치작.', 2023, '금속 골조, 구조색 광학 필름, 모터 구동 셀형 모듈 다수', NULL, ARRAY['키네틱아트','설치','빛','구조색','모터','김윤철']::text[], 'https://images.kctikinec.cloud/works/025.jpg', 'https://images.kctikinec.cloud/texts/025.txt', NULL, 0.663, 'CC BY-SA 4.0', 'Siarhei V / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Chroma_VII_kinetic_installation_Yunchul_Kim_CERN_Science_Gateway_June_2026_(11)_Side_view.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('디멘션스 (Dimensions)', '데이비드 C. 로이 (David C. Roy)', '태엽으로 구동되는 여러 개의 나무 바퀴가 회전하며 3차원 토러스 형태의 착시 패턴을 만들어내는 벽걸이형 키네틱 조각.', 2015, '목재(자작나무 합판 등), 태엽 구동 기계장치', NULL, ARRAY['키네틱아트','조각','회전','태엽','목재','Roy']::text[], 'https://images.kctikinec.cloud/works/037.jpg', 'https://images.kctikinec.cloud/texts/037.txt', NULL, 0.344, 'CC BY-SA 4.0', 'Marjiroy / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Dimensions_Kinetic_Sculpture_by_David_C._Roy_2015.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('키네틱 서클 (Kinetic Circle)', '필리스 마크 (Phyllis Mark)', '원형 테 안의 중심 형태가 나일론 실에 매달려 흔들리도록 만든 소형 키네틱 멀티플(펜던트 겸용) 조각.', 1972, '알루미늄에 23K 금도금, 나일론 실, 루사이트 받침대', NULL, ARRAY['키네틱아트','조각','모빌','알루미늄','금도금','Mark']::text[], 'https://images.kctikinec.cloud/works/068.jpg', 'https://images.kctikinec.cloud/texts/068.txt', NULL, 0.358, 'CC BY-SA 4.0', 'Phyllis Mark archives. Uploaded by Ira S. Mark, TTEE, Phyllis Mark Revocable Trust, the trust of the late artist''s estate. / Estate of Phyllis Mark / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:MOMACatalog1972-%27Kinetic_Circle%27.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('모빌 (Móvil)', '에우세비오 셈페레 (Eusebio Sempere)', '촘촘한 스틸 봉과 격자를 겹쳐 배치해 각도와 움직임에 따라 물결치는 무아레(moiré) 광학 효과를 내는 대형 키네틱 조각.', 1972, '스테인리스 스틸', NULL, ARRAY['키네틱아트','조각','무아레','스틸','옵아트','Sempere']::text[], 'https://images.kctikinec.cloud/works/073.jpg', 'https://images.kctikinec.cloud/texts/073.txt', NULL, 0.609, 'Public Domain', NULL, 'https://commons.wikimedia.org/wiki/File:M%C3%B3vil_(Eusebio_Sempere)_MEAL_Madrid_01.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('노틸러스 (Nautilus)', '데이비드 C. 로이 (David C. Roy)', '겹겹의 나무 링이 앵무조개 껍데기처럼 나선을 이루며 회전해 복합적이고 변화무쌍한 움직임을 만드는 태엽 구동 키네틱 조각.', 2014, '목재(자작나무 합판 등), 태엽 구동 기계장치', NULL, ARRAY['키네틱아트','조각','회전','태엽','목재','Roy']::text[], 'https://images.kctikinec.cloud/works/074.jpg', 'https://images.kctikinec.cloud/texts/074.txt', NULL, 0.185, 'CC BY-SA 4.0', 'Marjiroy / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Nautilus_Kinetic_Sculpture_by_David_C._Roy_2014.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('카리브의 진주 (The Pearl of the Caribbean)', '헤수스 라파엘 소토 (Jesús Rafael Soto)', '수많은 가느다란 금속 봉이 비처럼 촘촘히 매달려 바람과 시선의 이동에 따라 흔들리며 진동하는 키네틱 조각의 세부.', NULL, '매달린 수직 금속 봉/철사', NULL, ARRAY['키네틱아트','조각','바람','진동','금속','Soto']::text[], 'https://images.kctikinec.cloud/works/078.jpg', 'https://images.kctikinec.cloud/texts/078.txt', NULL, 0.326, 'CC BY 2.0', 'Javier D. Volcán R. from Porlamar / Isla de Margarita, Venezuela / LLuvia de Perla / Pearl Rain / CC BY 2.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pearl_Rain.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('크로마 VII (Chroma VII)', '김윤철 (Yunchul Kim)', '162개 링에 투명 폴리머 셀을 꿴 8자 매듭 형태의 대형 설치작으로, 셀의 기계적 변형으로 빛을 굴절시키며 숨 쉬듯 색이 어른거리는 키네틱·크로마틱 인스톨레이션.', 2023, '162개의 링, 투명 폴리머 비늘형 셀, 맞춤 액체 용매, 마이크로컨트롤러 구동 장치', NULL, ARRAY['키네틱아트','설치','빛','색채','모터','김윤철']::text[], 'https://images.kctikinec.cloud/works/085.jpg', 'https://images.kctikinec.cloud/texts/085.txt', NULL, 0.494, 'CC BY-SA 4.0', 'Oleslawlama / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Scientist_Siarhei_Besarab_Chroma_VII_artwork_CERN_Science_Gateway_June_2026_Geneva.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('이클립스 (Eclipse)', '드루 클로츠 (Drew Klotz)', '중심 기둥 위의 두 개의 링과 원반이 바람에 따라 균형을 이루며 흔들리고 회전하는 야외 키네틱 조각.', 2015, '금속(스테인리스 스틸·알루미늄 추정), 균형 회전 구조', NULL, ARRAY['키네틱아트','조각','바람','회전','스틸','Klotz']::text[], 'https://images.kctikinec.cloud/works/093.jpg', 'https://images.kctikinec.cloud/texts/093.txt', NULL, 0.814, 'CC BY 4.0', 'Artaxerxes / Own work / CC BY 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Construction_Williams_School_Building_216_West_Washington_Street_Lexington_VA_July_2024_03.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('파도를 묶는 자 (Wellenbinder)', '크리스티아네 뫼부스 (Christiane Möbus)', '안테나처럼 길게 뻗은 스틸 봉과 곡선 요소가 바람에 흔들리며 에너지와 파동을 연상시키는 야외 키네틱 조각.', 2000, '스테인리스 스틸', NULL, ARRAY['키네틱아트','조각','바람','스틸','야외조각','Möbus']::text[], 'https://images.kctikinec.cloud/works/101.jpg', 'https://images.kctikinec.cloud/texts/101.txt', NULL, 0.715, 'CC BY-SA 4.0', 'Siarhei Besarab / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kinetic_sculpture_%22Wellenbinder%22_by_Christiane_M%C3%B6bus_in_Greifswald.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('온리 브레스 (Only Breath)', '토러스 토러스 스튜디오스 (Torus Torus Studios)', '여러 개의 경첩식 패널로 이루어진 대형 매달린 구조가 천천히 오므라들고 펼쳐지며 호흡하듯 움직이는 키네틱 조각.', 2024, '금속 골조, 유리·거울 및 목재 패널(경첩식 접이 구조)', NULL, ARRAY['키네틱아트','조각','설치','모터','거울','Torus']::text[], 'https://images.kctikinec.cloud/works/103.jpg', 'https://images.kctikinec.cloud/texts/103.txt', NULL, 1.027, 'CC BY-SA 4.0', 'The wub / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Only_Breath_sculpture_-_Science_Museum,_London.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('두 개의 수직 사각형, 회전하며 하강 (Two Rectangles Vertical Gyratory Down)', '조지 리키 (George Rickey)', '두 개의 길쭉한 스테인리스 스틸 사각 판이 바람에 따라 축을 중심으로 천천히 회전·요동하는 야외 키네틱 조각.', 1970, '스테인리스 스틸', NULL, ARRAY['키네틱아트','조각','바람','회전','스틸','Rickey']::text[], 'https://images.kctikinec.cloud/works/106.jpg', 'https://images.kctikinec.cloud/texts/106.txt', NULL, 0.656, 'CC BY-SA 3.0', 'OTFW , Berlin / Self-photographed / CC BY-SA 3.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Skulptur_Hindenburgdamm_30_(Lifel)_Two_Rectangles_Vertical_Gyratory_Down%26George_Rickey%261970.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('베리에이션 II 선 (Variation II Sun)', '데이비드 C. 로이 (David C. Roy)', '곡선 살을 방사형으로 배치한 나무 바퀴들이 태엽으로 회전하며 만화경 같은 광학 패턴을 만드는 태엽 구동 키네틱 조각.', 2014, '목재(자작나무 합판 등), 태엽 구동 기계장치, 벨트 전동', NULL, ARRAY['키네틱아트','조각','회전','태엽','목재','Roy']::text[], 'https://images.kctikinec.cloud/works/118.jpg', 'https://images.kctikinec.cloud/texts/118.txt', NULL, 0.247, 'CC BY-SA 4.0', 'Marjiroy / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Variation_II_Sun_Kinetic_Sculpture_by_David_C._Roy_2014.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('윈드워드 캄 (Windward Calm)', '데이비드 로빈슨 (David Robinson)', '골조만 남은 나무 배 위에 선 인물상을 공중에 매달아, 항해하듯 천천히 흔들리며 도는 서스펜디드 키네틱 조각(세부).', NULL, '목재(늑골 구조의 배), 흰색으로 채색된 인물상, 매달림 구조', NULL, ARRAY['키네틱아트','조각','모빌','서스펜디드','목재','Robinson']::text[], 'https://images.kctikinec.cloud/works/129.jpg', 'https://images.kctikinec.cloud/texts/129.txt', NULL, 0.5, 'CC BY-SA 4.0', 'SageMacG / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Windward_Calm_detail1_Sage_MacGillivray.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('아멜리아 — 아멜리아 에어하트에게 바침 (Amelia / Homage to Amelia Earhart)', '메리 커티스 래트클리프 (Mary Curtis Ratcliff)', '커다란 흰 새틴 원반과 늘어뜨린 새틴 리본들이 공기 흐름에 나부끼며 흔들리는 매달린 직물 키네틱 조각(모빌).', 1972, '새틴, 플렉시글라스, 플라스틱, 나무, 모노필라멘트', NULL, ARRAY['키네틱아트','모빌','바람','새틴','직물','Ratcliff']::text[], 'https://images.kctikinec.cloud/works/000.jpg', 'https://images.kctikinec.cloud/texts/000.txt', NULL, 0.4, 'CC BY-SA 4.0', 'Mary Curtis Ratcliff / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:%22Amelia%22_(Homage_to_Amelia_Earhart)_by_Mary_Curtis_Ratcliff.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('레드 텀블 (Red Tumble)', '필리스 마크 (Phyllis Mark)', '무지개빛으로 채색된 알루미늄 슬랫으로 짜인 중앙 패널이 바람을 받아 회전하는 대형 옥외 키네틱 조각.', 1980, '알루미늄 프레임, 채색 알루미늄 슬랫', NULL, ARRAY['키네틱아트','바람','회전','알루미늄','마크']::text[], 'https://images.kctikinec.cloud/works/004.jpg', 'https://images.kctikinec.cloud/texts/004.txt', NULL, 0.104, 'CC BY-SA 4.0', 'Uploaded by Ira S. Mark, TTEE, Phyllis Mark Revocable Trust, the trust of the artist''s estate. / Estate of Phyllis Mark / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:%27Red_Tumble%27_by_Phyllis_Mark,_1980.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('지속되는 현재 (Folyamatos jelen / Present Continuous)', '로란드 카지 (Roland Kazi)', '금속 골조 위에 걸린 은빛 반사 막이 기계 장치로 수면처럼 출렁이는 키네틱 설치작.', 2018, '금속 프레임, 반사 필름(멤브레인), 모터, 영상 모니터', NULL, ARRAY['키네틱아트','모터','설치','영상','카지']::text[], 'https://images.kctikinec.cloud/works/041.png', 'https://images.kctikinec.cloud/texts/041.txt', NULL, 3.993, 'CC BY-SA 4.0', 'Zenon endless / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Folyamatos_jelen_-_kinetikus_install%C3%A1ci%C3%B3_-_2018.png');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('인벤터 릴리스드 (Inventor Released)', '데이비드 로이 (David C. Roy)', '나무 톱니바퀴들이 추의 힘으로 맞물려 지속적으로 회전하는 목제 키네틱 조각.', 1976, '목재(합판), 기어·크랭크 기계장치, 추 구동', NULL, ARRAY['키네틱아트','회전','목재','기어','로이']::text[], 'https://images.kctikinec.cloud/works/049.jpg', 'https://images.kctikinec.cloud/texts/049.txt', NULL, 0.036, 'CC BY-SA 4.0', 'Marjiroy / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Inventor_Released_-_Early_work_by_David_Roy_1976.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('문 스크린 (Moon Screen)', '필리스 마크 (Phyllis Mark)', '방사형으로 채색된 알루미늄 슬랫과 원형 ''달'' 형상이 접이식 병풍을 이루는 키네틱 설치작.', 1989, '알루미늄 프레임, 채색 알루미늄 슬랫', NULL, ARRAY['키네틱아트','알루미늄','빛','설치','마크']::text[], 'https://images.kctikinec.cloud/works/071.jpg', 'https://images.kctikinec.cloud/texts/071.txt', NULL, 0.087, 'CC BY-SA 4.0', 'Phyllis Mark. Uploaded by Ira S. Mark, TTEE, Phyllis Mark Revocable Trust, the trust of the late artist''s estate. / Estate of Phyllis Mark / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:MoonScreen02-1989.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('피라미드 버터플라이 (Pyramid Butterfly)', '필리스 마크 (Phyllis Mark)', '계단형·방사형으로 채색된 중앙 패널이 바람을 받아 수직축을 중심으로 회전하는 대형 옥외 키네틱 조각.', 1985, '채색 스틸·알루미늄', NULL, ARRAY['키네틱아트','바람','회전','스틸','마크']::text[], 'https://images.kctikinec.cloud/works/080.jpg', 'https://images.kctikinec.cloud/texts/080.txt', NULL, 0.094, 'CC BY-SA 4.0', 'Phyllis Mark. Uploaded by Ira S. Mark, TTEE, Phyllis Mark Revocable Trust, the trust of the late artist''s estate. / Estate of Phyllis Mark / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Phyllis_Mark,_%27Pyramid_Butterfly,%27_1985.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('윈드 인터벌스 (Wind Intervals)', '필리스 마크 (Phyllis Mark)', '물결치듯 굴곡진 세 개의 채색 강철 기둥이 각각 바람을 받아 제자리에서 회전하는 옥외 키네틱 조각.', 1976, '스테인리스강, 에나멜 도장 강철', NULL, ARRAY['키네틱아트','바람','회전','스틸','마크']::text[], 'https://images.kctikinec.cloud/works/081.jpg', 'https://images.kctikinec.cloud/texts/081.txt', NULL, 0.096, 'Public Domain', NULL, 'https://commons.wikimedia.org/wiki/File:Phyllis_Mark_%27Wind_Intervals,%27_1976.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('솔로 (Solo)', '데이비드 로이 (David C. Roy)', '새의 비행을 연상시키는 곡선 날개형 목재 부재들이 태엽 힘으로 유려하게 회전하는 키네틱 조각.', 2014, '목재(합판), 태엽(스프링) 기계장치', NULL, ARRAY['키네틱아트','회전','목재','태엽','로이']::text[], 'https://images.kctikinec.cloud/works/086.jpg', 'https://images.kctikinec.cloud/texts/086.txt', NULL, 0.056, 'CC BY-SA 4.0', 'Marjiroy / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Solo_Kinetic_Sculpture_by_David_C._Roy_2014.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('바카날 (Bacchanal)', '필리스 마크 (Phyllis Mark)', '산호처럼 가지 친 광택 알루미늄 형상이 모터 받침 위에서 회전하며 빛과 그림자를 흩뿌리는 탁상형 키네틱 조각.', 1968, '광택 아노다이즈드 알루미늄, 모터 구동 받침', NULL, ARRAY['키네틱아트','모터','회전','알루미늄','마크']::text[], 'https://images.kctikinec.cloud/works/002.jpg', 'https://images.kctikinec.cloud/texts/002.txt', NULL, 0.074, 'CC BY-SA 4.0', 'Uploaded by Ira S. Mark, TTEE, Phyllis Mark Revocable Trust, the trust of the artist''s estate. / Estate of Phyllis Mark / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:%27Bacchanal%27_by_Phyllis_Mark,1968.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('인터로킹 폼스 (Interlocking Forms)', '필리스 마크 (Phyllis Mark)', '광택 알루미늄 원형 테 안에서 타원형 부재가 매달려 흔들리도록 만든 키네틱 멀티플.', 1975, '광택 알루미늄', NULL, ARRAY['키네틱아트','회전','알루미늄','멀티플','마크']::text[], 'https://images.kctikinec.cloud/works/003.jpg', 'https://images.kctikinec.cloud/texts/003.txt', NULL, 0.078, 'CC BY-SA 4.0', 'Uploaded by Ira S. Mark, TTEE, Phyllis Mark Revocable Trust, the trust of the artist''s estate / Estate of Phyllis Mark / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:%27Interlocking_Forms%27_by_Phyllis_Mark.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('스윙잉 서클 (Swinging Circle)', '필리스 마크 (Phyllis Mark)', '광택 알루미늄 원형 테 안에 늘어선 곡선 슬랫들이 매달려 흔들리는 키네틱 멀티플.', 1972, '광택 알루미늄', NULL, ARRAY['키네틱아트','회전','알루미늄','멀티플','마크']::text[], 'https://images.kctikinec.cloud/works/005.jpg', 'https://images.kctikinec.cloud/texts/005.txt', NULL, 0.048, 'CC BY-SA 4.0', 'Uploaded by Ira S. Mark, TTEE, Phyllis Mark Revocable Trust, the trust of the artist''s estate. / Estate of Phyllis Mark / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:%27Swinging_Circle%27_by_Phyllis_Mark.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('모빌 8번 (Mobile No. 8)', '카렐 쿠리스마 (Kaarel Kurismaa)', '노란 원통형 몸체 중앙에서 빛이 맥동하고 꼭대기의 로터가 회전하는 키네틱 라이트 오브제.', 1980, '플라스틱, 금속, 전자장치, 조명', NULL, ARRAY['키네틱아트','빛','회전','모빌','쿠리스마']::text[], 'https://images.kctikinec.cloud/works/066.jpg', 'https://images.kctikinec.cloud/texts/066.txt', NULL, 0.109, 'CC BY-SA 4.0', 'Helen Melesk / Ragne Soosalu. – Kaarel Kurismaa. Yellow Light Orchecstra. ISBN 978-9949-485-86-4 . Ed. Ragne Soosalu. Tallinn, 2018 / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kurismaa_K_Mobile_1980_MG_3477.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('모듈레이터 V3 (Modulator V3)', '가보르 사우데르 (Gábor Szauder)', '타공 원반과 격자·거울면을 얹은 구조가 모터 턴테이블 위에서 회전하며 빛과 그림자를 흩뿌리는 라이트-키네틱 조각.', 2022, '스테인리스 스틸, 타공 금속판, 유리·아크릴, 회전 턴테이블, 모터, 조명', NULL, ARRAY['키네틱아트','빛','회전','모터','사우데르']::text[], 'https://images.kctikinec.cloud/works/100.jpg', 'https://images.kctikinec.cloud/texts/100.txt', NULL, 0.664, 'CC BY-SA 4.0', 'Globetrotter19 / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:G%C3%A1bor_Szauder_Modulator_V3,_V%C3%A1rosh%C3%A1zstrasse_9-11,_2024_Belv%C3%A1ros-Lip%C3%B3tv%C3%A1ros.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('모듈레이터 V3 (Modulator V3)', '가보르 사우데르 (Gábor Szauder)', '타공 원반과 나선 코일·격자 스크린이 모터 턴테이블 위에서 회전하며 빛과 그림자를 만들어 내는 라이트-키네틱 조각을 측면에서 본 모습.', 2022, '스테인리스 스틸, 타공 금속판, 유리·아크릴, 회전 턴테이블, 모터, 조명', NULL, ARRAY['키네틱아트','빛','회전','모터','사우데르']::text[], 'https://images.kctikinec.cloud/works/102.jpg', 'https://images.kctikinec.cloud/texts/102.txt', NULL, 0.588, 'CC BY-SA 4.0', 'Globetrotter19 / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Modulator_V3_(G%C3%A1bor_Szauder),_V%C3%A1rosh%C3%A1zstrasse_9-11,_2024_Belv%C3%A1ros-Lip%C3%B3tv%C3%A1ros.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('스웰 (Swell)', '도미닉 해리스 (Dominic Harris)', '천장 고리에서 다수의 발광 막대가 회전하며 물결(swell)처럼 빛의 파동을 만드는 대형 키네틱 라이트 조각.', 2019, '금속 링 구조, 조명(LED/광튜브), 모터 구동', NULL, ARRAY['키네틱아트','라이트아트','회전','모터','해리스']::text[], 'https://images.kctikinec.cloud/works/111.jpg', 'https://images.kctikinec.cloud/texts/111.txt', NULL, 0.536, 'CC BY-SA 4.0', 'Beepea3110 / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Swell_(2019)_-_by_Dominic_Harris.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('에오스 (Eos)', '장 팅겔리 (Jean Tinguely)', '검게 칠한 철제 바퀴와 기어, 곡선 아치들이 모터로 삐걱대며 돌아가는 팅겔리 특유의 키네틱 기계 조각.', NULL, '용접된 철·금속, 바퀴·기어, 모터', NULL, ARRAY['키네틱아트','모터','회전','기계','팅겔리']::text[], 'https://images.kctikinec.cloud/works/141.jpg', 'https://images.kctikinec.cloud/texts/141.txt', NULL, 0.551, 'CC BY-SA 2.0', 'Object Jean Tinguely Photograph Kat Sniffen from Cambridge, MA / 00007F060000-0.jpg / CC BY-SA 2.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Jerusalem_Tinguely_Eos.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('샘과 소용돌이 (Fonte e Vórtice)', '조앙 웨슬리 지 소자 (João Wesley de Souza)', '어두운 방 안 원형 수반에서 물이 소용돌이치고, 그 위로 조명이 통과해 벽에 일렁이는 빛 무늬를 투사하는 키네틱 설치.', 2000, '철, 물, 조명, 유압 시스템', NULL, ARRAY['키네틱아트','물','빛','설치','소자']::text[], 'https://images.kctikinec.cloud/works/006.jpg', 'https://images.kctikinec.cloud/texts/006.txt', NULL, 0.091, 'CC BY-SA 4.0', 'Johnnythegood / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:2000_fonte_e_vortice.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('데라이에렌델로에르 (deraierendelouer)', '시쿠 마샤두 (Chico Machado)', '원색으로 칠한 원반·톱니바퀴·도르래를 벽면에 조립해, 손으로 돌리면 움직이며 소리까지 나는 조작형 키네틱·사운드 회화.', 2007, '나무에 에나멜 페인트, 기어, 도르래, 체인', NULL, ARRAY['키네틱아트','회전','소리','회화','마샤두']::text[], 'https://images.kctikinec.cloud/works/014.jpg', 'https://images.kctikinec.cloud/texts/014.txt', NULL, 0.174, 'CC BY-SA 3.0', 'User:Tetraktys / [1] / CC BY-SA 3.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Chicomachado-pinturacin%C3%A9tic.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('바람에 실려 (Blowin'' in the Wind)', '빌리 라이헤 (Willi Reiche)', '폐부품과 오브제로 가득 찬 대형 기계 무대가 톱니바퀴·바퀴와 함께 움직이며 ''삶의 극장''을 연출하는 키네틱 설치.', NULL, '금속 프레임, 기어·바퀴, 발견된 오브제, 구동 장치(모터)', NULL, ARRAY['키네틱아트','모터','기계','설치','라이헤']::text[], 'https://images.kctikinec.cloud/works/064.gif', 'https://images.kctikinec.cloud/texts/064.txt', NULL, 17.369, 'CC BY-SA 4.0', 'Kumarem / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kunstmaschine_%27Blowin%27_in_the_Wind%27_von_Willi_Reiche_auf_der_NordArt_2025_in_B%C3%BCdelsdorf,_Deutschland.gif');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('뉴 코스모스 (New Cosmos)', '조앙 웨슬리 지 소자 (João Wesley de Souza)', '어두운 전시실에서 원형 수반의 물이 빛을 받아 파문과 소용돌이를 그리며 끊임없이 일렁이는 키네틱 설치작.', 1992, '철, 물, 빛, 전기기계식 제어 장치', NULL, ARRAY['키네틱아트','물','빛','설치','Souza']::text[], 'https://images.kctikinec.cloud/works/075.jpg', 'https://images.kctikinec.cloud/texts/075.txt', NULL, 0.061, 'CC BY-SA 4.0', 'Johnnythegood / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:New_cosmos_1992.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('나는 작은 집 (Fliegende Häuschen)', '조냐 프리드리히 (Sonya Friedrich)', '집 모양 알루미늄 판과 사각 날개가 축을 중심으로 바람에 따라 회전하고 균형을 잡으며 움직이는 바람 키네틱 조각.', 2014, '알루미늄', NULL, ARRAY['키네틱아트','바람','회전','알루미늄','Friedrich']::text[], 'https://images.kctikinec.cloud/works/087.jpg', 'https://images.kctikinec.cloud/texts/087.txt', NULL, 0.245, 'CC BY-SA 3.0', 'Sonya Friedrich / Own work / CC BY-SA 3.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sonya_Friedrich_-_Fliegende_H%C3%A4uschen_2014.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('라 시우다드 (La Ciudad)', '알렉산더 콜더 (Alexander Calder)', '검은 삼각 철판으로 이뤄진 고정형 스태빌 앞에 흰 원반이 달린 가는 금속 막대들이 균형을 이루며 공기 흐름에 따라 흔들리는 콜더의 스태빌-모빌 조각.', 1960, '채색한 철과 강철', NULL, ARRAY['키네틱아트','모빌','바람','조각','콜더']::text[], 'https://images.kctikinec.cloud/works/007.jpg', 'https://images.kctikinec.cloud/texts/007.txt', NULL, 0.445, 'CC BY 3.0', 'Ifigenia76 Fotografía: Hanna Carjevschi / Escultura: Alexander Calder / Own work / CC BY 3.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Alexander_Calder_-_La_Ciudad.JPG');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('거울이 있는 섹터 (Sector with Mirror)', '베르틸 헤를로우 스벤손 (Bertil Herlow Svensson)', '수많은 가느다란 알루미늄 막대가 부채꼴로 촘촘히 배열돼 비틀린 곡면을 이루며, 보는 각도에 따라 모아레·광학적 움직임을 만들어 내는 옵티컬-키네틱 조각.', 1968, '알루미늄 막대와 거울', NULL, ARRAY['키네틱아트','옵아트','알루미늄','조각','스벤손']::text[], 'https://images.kctikinec.cloud/works/013.jpg', 'https://images.kctikinec.cloud/texts/013.txt', NULL, 0.645, 'CC BY-SA 3.0', 'Thomas Ekström / Own work / CC BY-SA 3.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bertil_Herlow_Svensson.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('고든 브래트의 키네틱 시계 (Gordon Bradt Kinetic Clock)', '고든 브래트 (Gordon Bradt)', '수많은 톱니바퀴·나선 스프링·바퀴와 작은 인물상이 얽힌 대형 기계식 키네틱 시계 조각으로, 장치가 구동되면 부품들이 맞물려 돌아간다.', 1991, '스테인리스강 등 금속(톱니바퀴·스프링·막대)', NULL, ARRAY['키네틱아트','기계','톱니바퀴','시계','브래트']::text[], 'https://images.kctikinec.cloud/works/045.jpg', 'https://images.kctikinec.cloud/texts/045.txt', NULL, 0.551, 'CC BY-SA 4.0', 'Terri Bradt / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gordon_Bradt_Clock_in_Toronto_Airport_1991.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('관찰자 (Seher)', '울리케 문트 (Ulrike Mundt)', '삼각대 위에 얹힌 망원경 형태의 황동 관측기가 받침대를 축으로 방향을 틀며 도는 키네틱 조각이다.', 2016, '금속 삼각대, 황동관, 회전식 받침대', NULL, ARRAY['키네틱아트','회전','황동','조각','문트']::text[], 'https://images.kctikinec.cloud/works/116.jpg', 'https://images.kctikinec.cloud/texts/116.txt', NULL, 0.134, 'CC BY 4.0', 'Produzenten / Own work / CC BY 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ulrike_Mundt,_Seher,_kinetische_Skulptur,_2016.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('복잡성 관찰자 (Complexity Observer)', '드미트리 카바르가 (Dmitry Kawarga)', '가느다란 금속 봉과 작은 큐브들이 사방으로 뻗어 나가며 유기체 군집처럼 증식하는 바이오모픽 키네틱 조각이다.', 2013, '금속 봉·큐브·와이어 등으로 구성된 바이오모픽 구조물', NULL, ARRAY['키네틱아트','바이오모픽','금속','조각','카바르가']::text[], 'https://images.kctikinec.cloud/works/053.jpg', 'https://images.kctikinec.cloud/texts/053.txt', NULL, 0.178, 'CC BY-SA 4.0', 'Kawalena / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kawarga_Complexity_Observer.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('대지-존재 (erdsein)', '크리스티안 니엔하우스 (Christian Nienhaus)', '대륙이 그려진 철망 지구본이 공중에 매달려 내부에서 빛을 내고, 주위로 나비 날개 같은 요소들이 떠도는 키네틱 발광 오브제다.', NULL, '철사(와이어) 지구본, 내부 조명, 금속 날개형 요소 — 매달린 발광 오브제', NULL, ARRAY['키네틱아트','빛','지구본','모빌','니엔하우스']::text[], 'https://images.kctikinec.cloud/works/076.jpg', 'https://images.kctikinec.cloud/texts/076.txt', NULL, 0.044, 'CC BY-SA 3.0 de', 'Christian Nienhaus / CC BY-SA 3.0 de / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Nienhaus-erdsein.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('변화하는 주사위 그림 (Dice / changing painting)', '울리 아셴보른 (Uli Aschenborn)', '관람자가 앞을 지나 시점을 바꾸면 주사위 눈의 수와 색이 1·2·3으로 달라지는, 물감과 모래로 그린 변화하는 회화다.', NULL, '물감과 모래로 그린 변화하는 회화(관람자 이동형 시차 방식)', NULL, ARRAY['키네틱아트','옵아트','착시','회화','아셴보른']::text[], 'https://images.kctikinec.cloud/works/113.gif', 'https://images.kctikinec.cloud/texts/113.txt', NULL, 4.864, 'CC BY-SA 4.0', 'Uli Aschenborn / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Uli_Aschenborn_-_Dice_showing_1_2_or_3_pips_-_AUTORUN.gif');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('에오스 xk (3) (Eos xk (3))', '장 팅겔리 (Jean Tinguely)', '검은 철제 바퀴·아치·핸들이 비스듬한 기둥 위에 얽혀 모터로 삐걱대며 돌아가는 팅겔리 특유의 기계식 키네틱 조각이다.', 1965, '채색된 강철·철제 부품 (모터 구동 기계 조각)', NULL, ARRAY['키네틱아트','모터','기계장치','조각','팅겔리']::text[], 'https://images.kctikinec.cloud/works/137.jpg', 'https://images.kctikinec.cloud/texts/137.txt', NULL, 0.199, 'Public Domain', NULL, 'https://commons.wikimedia.org/wiki/File:Eos_xk_(3),_1965.JPG');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('키네틱 맨 (Kinetic Man / K-Man)', '러스 루퍼트 (Russ Rupert)', '사람 형상을 층층이 쌓아 올린 대형 키네틱 조각으로, 부분들이 움직이도록 만든 야외 조형물.', NULL, '금속(도색된 금속·목재 블록 추정)', NULL, ARRAY['키네틱아트','조각','야외조각','금속','Rupert']::text[], 'https://images.kctikinec.cloud/works/052.jpg', 'https://images.kctikinec.cloud/texts/052.txt', NULL, 0.751, 'CC BY-SA 4.0', 'ColletteParker / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:K-Man_(Kinetic_Man)_installed_at_Jefferson_Avenue_Footbridge.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('선셋, 선라이즈, 선셋 (Sunset, Sunrise, Sunset)', '알렉산드르 다 쿠냐 (Alexandre da Cunha)', '역사 내 광고판을 회전시켜 노을빛 색면이 계속 바뀌게 하는, 지하철역에 통합된 색채 키네틱 설치작.', 2021, '회전식 광고판(빌보드) 패널, 지하철 역사 환경 설치', NULL, ARRAY['키네틱아트','설치','회전','색채','공공미술','Cunha']::text[], 'https://images.kctikinec.cloud/works/110.jpg', 'https://images.kctikinec.cloud/texts/110.txt', NULL, 0.577, 'CC BY-SA 4.0', 'Turini2 / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sunset,_Sunrise,_Sunset_by_Alexandre_da_Cunha.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('롤링 볼 조각 (Rolling Ball Sculpture)', '아르카디우시 카민스키 (Arkadiusz Kamiński)', '나선형 금속 레일을 따라 구슬이 끝없이 굴러 내려가고 다시 위로 올려지는 ''롤링 볼'' 키네틱 조각.', NULL, '스테인리스강 트랙, 구슬, 목재 받침, 리프트 기계장치', NULL, ARRAY['키네틱아트','회전','구슬','스틸','카민스키']::text[], 'https://images.kctikinec.cloud/works/083.jpg', 'https://images.kctikinec.cloud/texts/083.txt', NULL, 0.432, 'CC BY-SA 4.0', 'Areklodzpl / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Rolling_Ball_Sculpture_(RBS)_Arkadiusz_Kami%C5%84ski_Kineticart.eu.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('앤드루 카슨의 바람 조각 (제목 미상)', '앤드루 카슨 (Andrew Carson)', '긴 기둥 위의 소용돌이·잎 모양 금속 날개와 유리 장식이 바람을 받아 여러 층에서 회전하는 바람 키네틱 조각.', NULL, '금속(구리·강철), 채색 유리', NULL, ARRAY['키네틱아트','바람','회전','유리','카슨']::text[], 'https://images.kctikinec.cloud/works/104.jpg', 'https://images.kctikinec.cloud/texts/104.txt', NULL, 0.954, 'CC0', NULL, 'https://commons.wikimedia.org/wiki/File:Sculpture_in_Maple_Leaf_Community_Gardens.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('세 개의 정사각형, 수직 대각 (Three Squares Vertical Diagonal)', '조지 리키 (George Rickey)', '대각선으로 세운 세 개의 대형 스테인리스강 정사각 판이 바람을 받아 축을 중심으로 천천히 흔들리는 키네틱 조각.', NULL, '스테인리스강', NULL, ARRAY['키네틱아트','바람','회전','스틸','리키']::text[], 'https://images.kctikinec.cloud/works/112.jpg', 'https://images.kctikinec.cloud/texts/112.txt', NULL, 0.317, 'CC BY-SA 4.0', 'Oysters mate / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Three_Squares_Vertical_Diagonal.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('그로잉 폼 (Growing Form)', '필리스 마크 (Phyllis Mark)', '유기적으로 잘린 원형 알루미늄 판이 모터 구동 받침대 위에서 천천히 회전하며 움직이는 그림자를 만드는 키네틱 조각.', 1968, '알루미늄, 모터 구동 받침대', NULL, ARRAY['키네틱아트','모터','회전','알루미늄','Mark']::text[], 'https://images.kctikinec.cloud/works/084.jpg', 'https://images.kctikinec.cloud/texts/084.txt', NULL, 0.08, 'CC BY-SA 4.0', 'Phyllis Mark. Uploaded by Ira S. Mark, TTEE, Phyllis Mark Revocable Trust, the trust of the late artist''s estate. / Estate of Phyllis Mark / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:RuthWhiteAnnouncement1968.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('포커스 (FOCUS)', 'HAEL YXXS', '숲을 배경으로 하늘에 떠 있는 가느다란 금속 타원 고리가 바람에 흔들리는 미니멀 야외 키네틱 설치작.', 1993, '금속 링/와이어 (야외 설치)', NULL, ARRAY['키네틱아트','야외설치','바람','미니멀','링']::text[], 'https://images.kctikinec.cloud/works/040.jpg', 'https://images.kctikinec.cloud/texts/040.txt', NULL, 0.35, 'CC BY-SA 4.0', 'Herr LehmannX / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:FOCUS.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('키네틱 프리즈 (Friso Cinético)', '마틸데 페레스 (Matilde Pérez)', '길게 이어진 벽면을 따라 기하학적 금속 패널이 반복 배열돼, 지나가며 볼 때 광학적으로 움직이는 듯한 착시를 일으키는 대형 키네틱 프리즈(벽면 부조).', NULL, '금속(알루미늄) 패널', NULL, ARRAY['키네틱아트','옵아트','금속','공공미술','페레스']::text[], 'https://images.kctikinec.cloud/works/042.jpg', 'https://images.kctikinec.cloud/texts/042.txt', NULL, 0.393, 'CC BY-SA 4.0', 'ElPabloRN / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Frisocinetico.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('키네틱 아트 (점 격자 옵아트 회화, Kinetic Art)', '다리우시 스톨라진 (Dariusz Stolarzyn)', '주황·노랑 원들이 격자로 빼곡히 배열되고 그 위로 나선형 곡선이 지나가며, 원들이 회전·이동하는 듯한 광학적 움직임을 만드는 옵아트 회화.', NULL, '캔버스에 유채(옵아트 회화)', NULL, ARRAY['키네틱아트','옵아트','회화','착시','스톨라진']::text[], 'https://images.kctikinec.cloud/works/061.jpg', 'https://images.kctikinec.cloud/texts/061.txt', NULL, 0.524, 'CC BY-SA 4.0', 'Dariusz stolarzyn / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kinetic_art.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('르 데르니에 크리 (Le dernier cri, 마지막 외침)', '빌리 라이헤 (Willi Reiche)', '동물 두개골과 가죽 마구를 낡은 철제 바퀴·대차 기계장치에 결합한 어셈블리지 키네틱 머신으로, 모터로 구동되면 바퀴와 부품이 삐걱대며 움직인다.', NULL, '금속(철), 가죽 마구, 동물 두개골, 목재 대차, 전기 모터', NULL, ARRAY['키네틱아트','모터','기계','어셈블리지','라이헤']::text[], 'https://images.kctikinec.cloud/works/065.gif', 'https://images.kctikinec.cloud/texts/065.txt', NULL, 52.272, 'CC BY-SA 4.0', 'Willi Reiche / Die Aufnahme habe ich selbst erstellt und das Einverständnis des Künstlers Willi Reiche eingeholt, die Videosequenz als *.gif bei Wikimedia hochzuladen. / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kunstmaschine_%E2%80%9ELe_dernier_cri%E2%80%9C_des_Wachtberger_Kinetikk%C3%BCnstlers_Willi_Reiche_im_%E2%80%9EHaus_an_der_Redoute%E2%80%9C,_Bonn,_Bad_Godesberg.gif');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('키네틱 아트 (점 격자 옵아트 회화, Lot.01112018)', '다리우시 스톨라진 (Dariusz Stolarzyn)', '청회색 바탕에 은빛 원들이 격자로 배열되고 소용돌이 곡선이 겹쳐, 나선이 회전하며 원들이 물결치는 듯한 광학적 움직임을 일으키는 옵아트 회화.', NULL, '캔버스에 유채(옵아트 회화)', NULL, ARRAY['키네틱아트','옵아트','회화','착시','스톨라진']::text[], 'https://images.kctikinec.cloud/works/067.jpg', 'https://images.kctikinec.cloud/texts/067.txt', NULL, 0.4, 'CC BY-SA 4.0', 'Dariusz stolarzyn / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lot.01112018.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('퍼시픽 사이언스 센터 키네틱 시계 (Pacific Science Center Clock)', '고든 브래트 (Gordon Bradt)', '천장까지 솟은 금속 탑 안에서 기어와 코일, 나선형 트랙을 따라 부품과 공이 오르내리며 작동하는 대형 기계식 키네틱 시계다.', NULL, '금속 프레임, 기어, 스프링 코일, 나선형 트랙, 유리 기둥 등으로 구성된 대형 기계식 키네틱 장치', NULL, ARRAY['키네틱아트','기계장치','기어','시계','브래트']::text[], 'https://images.kctikinec.cloud/works/077.jpg', 'https://images.kctikinec.cloud/texts/077.txt', NULL, 0.174, 'CC BY-SA 4.0', 'Terri Bradt / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pacific_Science_Center_Clock.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('균형 조각 (Balance Sculpture 08)', NULL, '무거운 목재 보를 콘크리트 기단 위 한 점에 아슬아슬하게 얹어 바람이나 접촉에 따라 미세하게 흔들리도록 한 균형 조각.', NULL, '목재 침목, 벽돌, 콘크리트 기단, 금속 지지대', NULL, ARRAY['키네틱아트','균형','조각','목재','설치']::text[], 'https://images.kctikinec.cloud/works/012.jpg', 'https://images.kctikinec.cloud/texts/012.txt', NULL, 0.599, 'CC BY-SA 4.0', 'OhioOakTree (flickr username: "Vince Reinhart") / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Balance_sculpture_08.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('에브리 브라스 유 테이크 (Every brass you take)', NULL, '여러 개의 황동 나팔 벨을 가느다란 금속 대에 매달아 위아래로 까딱이며 흔들리게 한 키네틱 조각.', NULL, '황동 나팔(혼) 벨, 금속 로드·스탠드, 구동 장치(모터 등)', NULL, ARRAY['키네틱아트','모터','황동','조각','그림자']::text[], 'https://images.kctikinec.cloud/works/038.gif', 'https://images.kctikinec.cloud/texts/038.txt', NULL, 20.279, 'CC BY-SA 4.0', 'Kunstmaschinen / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Every_brass_you_take.gif');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('빈트쿠치 / 바람 마차 (WindKutsche / Wind Chariot)', NULL, '로마 전차를 닮은 몸체 위 로터가 바람에 돌면 체인으로 동력이 전달되어, 막대를 딛고 바람을 거슬러 뒤뚱뒤뚱 전진하는 풍력 키네틱 조각.', NULL, '강철·금속, 대형 바퀴, 스테인리스 로터, 체인 구동부', NULL, ARRAY['키네틱아트','바람','회전','조각','바퀴']::text[], 'https://images.kctikinec.cloud/works/058.jpg', 'https://images.kctikinec.cloud/texts/058.txt', NULL, 0.378, 'CC BY-SA 3.0', 'Kinetics / Own work / CC BY-SA 3.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kineic_Art_WindKutsche.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('자성 키네틱 조각 (Magnetic Kinetic Sculpture)', NULL, '받침대 위에서 회전하는 자성 키네틱 조각을 장노출로 촬영해, 빛의 궤적이 초록·노랑·파랑·보라의 나선 무늬로 남은 이미지.', NULL, '자석, 회전 구동부, 발광·반사 요소, 받침대', NULL, ARRAY['키네틱아트','회전','자석','빛','조각']::text[], 'https://images.kctikinec.cloud/works/059.jpg', 'https://images.kctikinec.cloud/texts/059.txt', NULL, 0.399, 'CC BY 2.0', 'Sheila Sund from Salem, United States / Kinetic Sculpture / CC BY 2.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kinetic_Sculpture_(25005505015).jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('아쿠아리우스 램프 (Aquarius Lamp)', NULL, '떨어지는 물줄기에 RGB LED를 특정 주파수로 점멸시켜, 물이 나선으로 휘며 위로 솟는 듯한 착시를 만드는 키네틱 라이트-워터 장치.', NULL, '물 펌프, RGB LED, 물줄기, 목재 프레임', NULL, ARRAY['키네틱아트','빛','물','LED','착시']::text[], 'https://images.kctikinec.cloud/works/008.gif', 'https://images.kctikinec.cloud/texts/008.txt', NULL, 4.03, 'CC BY-SA 4.0', 'Corinth777 / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Aquarius_Lamp.gif');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('달리는 키네틱 조각 (Kinetic Sculpture in Motion)', NULL, '여러 개의 바퀴와 페달로 구성된 해양 테마의 인력 구동 키네틱 조각을, 참가자들이 직접 타고 거리를 달리는 키네틱 조각 경주 장면.', NULL, '자전거 부품, 다중 바퀴, 금속 프레임, 해파리·산호 등 장식물', NULL, ARRAY['키네틱아트','인력구동','바퀴','조각','퍼레이드']::text[], 'https://images.kctikinec.cloud/works/060.jpg', 'https://images.kctikinec.cloud/texts/060.txt', NULL, 0.79, 'CC BY-SA 4.0', 'MarylandGeoffrey / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kinetic_Sculpture_in_Motion.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('달의 위상 키네틱 조각 (Phases of the Moon kinetic sculpture)', NULL, '인물 형상의 금속 조각이 초승달과 원반을 받쳐 들고 바람에 따라 흔들리며 달의 위상 변화를 표현하는 야외 키네틱 조각.', NULL, '금속(강철 와이어 및 판)', NULL, ARRAY['키네틱아트','바람','회전','조각','달']::text[], 'https://images.kctikinec.cloud/works/090.jpg', 'https://images.kctikinec.cloud/texts/090.txt', NULL, 0.26, 'CC BY-SA 2.0', 'Stanley Howe / Geograph Britain and Ireland / CC BY-SA 2.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:A_kinetic_%27phases_of_the_moon%27_sculpture_-_geograph.org.uk_-_3525831.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('아쿠아리우스 램프 — 화산 번개 (Aquarius Lamp, Volcanic Lightning)', NULL, '떨어지는 물줄기에 RGB LED를 특정 주파수로 점멸(스트로브)시켜 물이 번개처럼 갈라지고 멈춘 듯 보이게 하는 스트로브 분수 램프.', NULL, '물 분수, RGB LED 스트로브, 반투명 몸체', NULL, ARRAY['키네틱아트','빛','물','LED','분수']::text[], 'https://images.kctikinec.cloud/works/009.gif', 'https://images.kctikinec.cloud/texts/009.txt', NULL, 4.674, 'CC BY-SA 4.0', 'Corinth777 / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Aquarius_Lamp_Volcanic_Lightning.gif');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('기바트 람의 바람 키네틱 조각 (Kinetic Sculpture, Givat Ram)', NULL, '반사 연못 위에 세운 흰 금속 기둥 끝에서 가는 막대들이 바람을 받아 회전·요동하며, 1분 간격의 두 장면에서 막대 위치가 달라져 움직임이 드러나는 바람 키네틱 조각.', NULL, '채색한 금속(강철) 막대와 기둥', NULL, ARRAY['키네틱아트','바람','회전','조각','균형']::text[], 'https://images.kctikinec.cloud/works/062.jpg', 'https://images.kctikinec.cloud/texts/062.txt', NULL, 0.498, 'CC BY-SA 3.0', 'User:Ranbar / Own work / CC BY-SA 3.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kinetic_art_givat_ram.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('게르스트호펜 바람 조각 (Wind Sculpture, Gersthofen)', NULL, '세 개의 높은 기둥 위에서 나선형 금속 날개와 채색된 반원 원반들이 바람을 받아 제각기 회전하는 야외 풍력 키네틱 조각이다.', NULL, '스테인리스 스틸과 채색 금속; 바람으로 회전하는 나선형·원반형 날개', NULL, ARRAY['키네틱아트','바람','회전','스틸','조각']::text[], 'https://images.kctikinec.cloud/works/098.jpg', 'https://images.kctikinec.cloud/texts/098.txt', NULL, 1.238, 'CC BY 4.0', '-wuppertaler / Own work / CC BY 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:GER_Gersthofen,_R%C3%BCgener_Park_0005.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('물의 이중주 분수 (Fontana Duetto d''Acqua)', NULL, '발처럼 수직으로 떨어지는 물의 장막 앞에서 금속 프로펠러형 날개가 물살을 받아 회전하는 분수형 키네틱 설치다.', NULL, '금속과 물; 물살로 도는 프로펠러형 날개', NULL, ARRAY['키네틱아트','물','분수','회전','설치']::text[], 'https://images.kctikinec.cloud/works/131.jpg', 'https://images.kctikinec.cloud/texts/131.txt', NULL, 0.689, 'CC BY-SA 4.0', 'Alexmar983 / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:2018-09-14_Fontana_Acqua_Piazza_Domenico_Giusti_01.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('이스라엘 미술관 야외 금속 조각 (Israel Museum outdoor metal sculpture)', NULL, '커다란 원형 링과 각진 금속 판·빔이 얽힌 대형 추상 금속 조각으로, 하늘을 배경으로 실루엣처럼 보인다.', NULL, '강철 등 금속 (용접 조각)', NULL, ARRAY['키네틱아트','금속','스틸','조각','추상']::text[], 'https://images.kctikinec.cloud/works/169.jpg', 'https://images.kctikinec.cloud/texts/169.txt', NULL, 0.124, 'CC BY-SA 2.0', 'Xavier Gillet, Bordeaux, France ( xavier33300 on flickr) / Musée de Jérusalem - Israël / CC BY-SA 2.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mus%C3%A9e_de_J%C3%A9rusalem_-_Isra%C3%ABl_(7556056486).jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('회전하는 듯한 동심원 옵아트 (Art cinétique)', NULL, '흑백의 동심원과 화살무늬가 겹쳐 응시하면 전체가 서서히 회전하는 듯한 착시를 일으키는 옵아트·키네틱 이미지다.', NULL, '흑백 동심원·화살 패턴 (매체 미상, 옵아트 이미지)', NULL, ARRAY['키네틱아트','옵아트','착시','흑백','회전']::text[], 'https://images.kctikinec.cloud/works/010.jpg', 'https://images.kctikinec.cloud/texts/010.txt', NULL, 0.055, 'CC BY-SA 4.0', 'Lithograveur / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Art_cin%C3%A9tique,_Michel_Robardet.jpg');
insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('기하학적 순열 4 (Permutazione geometrica 4)', NULL, '손으로 만든 아크릴 셀들에 채운 색색의 액체가 격자를 이루며, 기울임에 따라 색과 무늬가 흐르며 바뀌는 액체 회화다.', NULL, '손으로 제작한 메타크릴레이트(아크릴) 셀에 채운 채색 액체', NULL, ARRAY['키네틱아트','액체','기하추상','아크릴','옵아트']::text[], 'https://images.kctikinec.cloud/works/079.jpg', 'https://images.kctikinec.cloud/texts/079.txt', NULL, 0.051, 'CC BY-SA 4.0', 'Terrainvista / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Permutazione_geometrica_4.jpg');
